// Round trips: loops of about a chosen distance from a start, generated by
// Polku and routed as ordinary routes (start → a few via points → start), so
// everything else (route styles, batching, the stand-in router, editing,
// share links) just works, and a loop you pick is a normal route.
//
// Shape: the start sits on a circle and the via points go round it, so the
// loop rides a ring rather than out-and-back spokes. Its radius comes from
// the target and how much longer than the circle each sport's routes ride
// (calibrated with tools/loop_probe.py against a local BRouter, 2026-10-13).
// Finland is full of water, and a via point in a lake means a failed route or
// a long way round, so directions are chosen and via points nudged with the
// water the map already has loaded, before any routing call.

import { dist } from './geo.js';

// route length ÷ circle length, per sport (median of 30 loops each)
// (×0.88 after the water-aware directions: they avoid the long ways round, so loops came out a little short)
const DETOUR = { mtb: 1.35, gravel: 1.57, road: 1.45, hike: 1.23, trailrun: 1.19, run: 1.12 };
const VIAS = 4;
export const roundTripSports = Object.keys(DETOUR);

const R = 6371000;
export function destination([lon, lat], m, bearing) {
  const b = (bearing * Math.PI) / 180, d = m / R, la1 = (lat * Math.PI) / 180, lo1 = (lon * Math.PI) / 180;
  const la2 = Math.asin(Math.sin(la1) * Math.cos(d) + Math.cos(la1) * Math.sin(d) * Math.cos(b));
  const lo2 = lo1 + Math.atan2(Math.sin(b) * Math.sin(d) * Math.cos(la1), Math.cos(d) - Math.sin(la1) * Math.sin(la2));
  return [+((lo2 * 180) / Math.PI).toFixed(6), +((la2 * 180) / Math.PI).toFixed(6)];
}

/** The circle a loop of `targetM` rides, for a sport: its radius in metres. */
export const radiusFor = (sport, targetM) => targetM / (2 * Math.PI * (DETOUR[sport] || 1.5));

// a point on the loop's circle: `bearing` points from the start to the centre; `a` turns round it clockwise
const onCircle = (start, r, bearing, a) => destination(destination(start, r, bearing), r, (bearing + 180 + a) % 360);

/** The area a set of loops can reach (for framing the map before reading its water). */
export function reach(start, r) {
  const pad = 2.2 * r;
  return [destination(start, pad, 270)[0], destination(start, pad, 180)[1], destination(start, pad, 90)[0], destination(start, pad, 0)[1]];
}

// ---------------------------------------------------------------- water, from the loaded vector tiles
/** Water polygons of the map's loaded tiles, with a point-in-water test. */
export function waterOf(map) {
  const polys = [];
  let feats = [];
  try { feats = map.querySourceFeatures('ofm', { sourceLayer: 'water' }); } catch { /* no tiles yet */ }
  for (const f of feats) {
    if (f.properties.class === 'swimming_pool') continue;
    const g = f.geometry;
    const list = g.type === 'Polygon' ? [g.coordinates] : g.type === 'MultiPolygon' ? g.coordinates : [];
    for (const rings of list) {
      let x0 = 180, y0 = 90, x1 = -180, y1 = -90;
      for (const [x, y] of rings[0]) { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
      polys.push({ rings, bb: [x0, y0, x1, y1] });
    }
  }
  const inRing = ([x, y], ring) => {
    let inside = false;
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const [xi, yi] = ring[i], [xj, yj] = ring[j];
      if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
    }
    return inside;
  };
  return {
    count: polys.length,
    isWater: (p) => polys.some(({ rings, bb }) => p[0] >= bb[0] && p[0] <= bb[2] && p[1] >= bb[1] && p[1] <= bb[3]
      && inRing(p, rings[0]) && !rings.slice(1).some((hole) => inRing(p, hole))),
  };
}

/**
 * Candidate loops before routing: for each direction, the via points (nudged
 * along the circle off any water) and how much of the circle is water. The
 * best `count` directions, spread out, come first. No network.
 */
export function plan({ start, sport, targetM, direction = null, count = 3, water, spin = 0 }) {
  const r = radiusFor(sport, targetM);
  const bearings = direction == null
    ? Array.from({ length: 12 }, (_, i) => (i * 30 + spin) % 360)
    : [-40, -20, 0, 20, 40].map((d) => (direction + d + 360) % 360);
  const options = bearings.map((b) => {
    // how wet the circle is (36 samples)
    let wet = 0;
    for (let k = 1; k < 36; k++) if (water.isWater(onCircle(start, r, b, k * 10))) wet++;
    // via points evenly round it, each moved to the nearest dry spot along the circle (up to ±35°)
    const vias = [];
    let stuck = 0;
    for (let k = 1; k <= VIAS; k++) {
      const a = (k * 360) / (VIAS + 1);
      const tries = [0, 8, -8, 16, -16, 25, -25, 35, -35];
      const t = tries.find((d) => !water.isWater(onCircle(start, r, b, a + d)));
      if (t == null) stuck++;
      vias.push(onCircle(start, r, b, a + (t || 0)));
    }
    return { bearing: b, r, points: [start, ...vias, start.slice()], wet: wet / 35, stuck };
  });
  // fewest via points stuck in water, then the driest circle; when no direction was asked for, keep them ≥ 60° apart
  options.sort((x, y) => x.stuck - y.stuck || x.wet - y.wet || (direction == null ? 0 : Math.abs(angleDiff(x.bearing, direction)) - Math.abs(angleDiff(y.bearing, direction))));
  const out = [];
  for (const o of options) {
    if (out.length >= count) break;
    if (direction == null && out.some((p) => Math.abs(angleDiff(p.bearing, o.bearing)) < 60)) continue;
    out.push(o);
  }
  for (const o of options) if (out.length < count && !out.includes(o)) out.push(o);
  return out;
}

const angleDiff = (a, b) => ((a - b + 540) % 360) - 180;

/** The same circle, resized so the loop rides about the target (after a first try missed it). */
export function resize(option, actualM, targetM, start, water) {
  const k = Math.max(0.6, Math.min(1.5, targetM / actualM));
  const r = option.r * k;
  const vias = option.points.slice(1, -1).map((_, i) => {
    const a = ((i + 1) * 360) / (VIAS + 1);
    const t = [0, 8, -8, 16, -16, 25, -25].find((d) => !water.isWater(onCircle(start, r, option.bearing, a + d)));
    return onCircle(start, r, option.bearing, a + (t || 0));
  });
  return { ...option, r, points: [start, ...vias, start.slice()], resized: true };
}

/** How much of a line is ridden twice: the share of it within 15 m of a part at least 300 m away along it. */
export function twiceShare(coords) {
  const pts = [coords[0]], along = [0];
  for (const c of coords.slice(1)) {
    const d = dist(pts[pts.length - 1], c);
    if (d >= 20) { along.push(along[along.length - 1] + d); pts.push(c); }
  }
  const cell = new Map();
  const key = (p) => `${Math.floor(p[0] / 0.0003)},${Math.floor(p[1] / 0.00015)}`;
  pts.forEach((p, i) => { const k = key(p); if (!cell.has(k)) cell.set(k, []); cell.get(k).push(i); });
  let twice = 0;
  pts.forEach((p, i) => {
    const cx = Math.floor(p[0] / 0.0003), cy = Math.floor(p[1] / 0.00015);
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        for (const j of cell.get(`${cx + dx},${cy + dy}`) || []) {
          if (Math.abs(along[j] - along[i]) > 300 && dist(p, pts[j]) < 15) { twice++; return; }
        }
      }
    }
  });
  return pts.length ? twice / pts.length : 0;
}

/** Lower is better: off-target distance, riding the same way twice, and heads-up items. */
export const score = ({ km, targetKm, twice, warnings }) => 100 * Math.abs(km - targetKm) / targetKm + 60 * twice + 2 * warnings;

/** A time target as a distance, with the speeds the time estimate uses (phase 6). */
export function distanceForTime(sport, minutes, speeds) {
  const kmh = sport === 'hike' ? speeds.walk * 0.9
    : sport === 'run' || sport === 'trailrun' ? (speeds.paved + speeds.trail) / 2 * 0.95
      : sport === 'road' ? speeds.paved * 0.9
        : (speeds.paved * 0.3 + speeds.unpaved * 0.4 + speeds.trail * 0.3) * 0.9;
  return (minutes / 60) * kmh * 1000;
}
